class Solution:
    def minimumOperations(self, grid: List[List[int]]) -> int:
        m, n = len(grid), len(grid[0])
        eq = [[0] * 10 for _ in range(n)]
        for j in range(n):
            for i in range(m):
                eq[j][grid[i][j]] += 1
        INF = float('inf')
        dp = [m - eq[0][v] for v in range(10)]
        for j in range(1, n):
            ndp = [INF] * 10
            for v in range(10):
                best = min(dp[u] for u in range(10) if u != v)
                ndp[v] = m - eq[j][v] + best
            dp = ndp
        return min(dp)

