from functools import lru_cache

class Solution:
    def minimumOperations(self, grid: List[List[int]]) -> int:
        m, n = len(grid), len(grid[0])
        eq = [[0] * 10 for _ in range(n)]
        for j in range(n):
            for i in range(m):
                eq[j][grid[i][j]] += 1
        @lru_cache(maxsize=None)
        def solve(j, prev):
            if j == n:
                return 0
            return min(m - eq[j][v] + solve(j + 1, v)
                       for v in range(10) if v != prev)
        return solve(0, -1)

