class Solution {
    int m, n;
    vector<array<int, 10>> eq;
    vector<array<int, 11>> memo;
    int solve(int j, int prev) {
        if (j == n) return 0;
        int& r = memo[j][prev + 1];
        if (r != -1) return r;
        r = INT_MAX;
        for (int v = 0; v < 10; v++)
            if (v != prev) r = min(r, m - eq[j][v] + solve(j + 1, v));
        return r;
    }
public:
    int minimumOperations(vector<vector<int>>& grid) {
        m = grid.size(); n = grid[0].size();
        eq.assign(n, {});
        for (int j = 0; j < n; j++)
            for (int i = 0; i < m; i++) eq[j][grid[i][j]]++;
        memo.assign(n, {});
        for (auto& row : memo) row.fill(-1);
        return solve(0, -1);
    }
};

