    int[][] eq, memo;
    int solve(int j, int prev) {
        if (j == n) return 0;
        if (memo[j][prev + 1] != -1) return memo[j][prev + 1];
        int best = Integer.MAX_VALUE;
        for (int v = 0; v < 10; v++)
            if (v != prev) best = Math.min(best, m - eq[j][v] + solve(j + 1, v));
        return memo[j][prev + 1] = best;
    }
    public int minimumOperations(int[][] grid) {
        m = grid.length; n = grid[0].length;
        eq = new int[n][10];
        for (int j = 0; j < n; j++)
            for (int i = 0; i < m; i++) eq[j][grid[i][j]]++;
        memo = new int[n][11];
        for (int[] row : memo) java.util.Arrays.fill(row, -1);
        return solve(0, -1);
    }
}

